TERMINAL = ("completed", "failed", "canceled")


def _text_of(message):
    return " ".join(part["text"] for part in message.get("parts", [])
                    if part.get("kind") == "text")


def run_agent(requests, vocabulary):
    tasks = {}
    order = []
    counter = [0]
    responses = []

    def reply(rid, **body):
        responses.append({"jsonrpc": "2.0", "id": rid, **body})

    for request in requests:
        rid = request.get("id")
        method = request.get("method")
        params = request.get("params") or {}

        if method == "message/send":
            message = params["message"]
            task_id = params.get("taskId")
            if task_id is None:
                counter[0] += 1
                task_id = f"task-{counter[0]}"
                task = {"id": task_id, "contextId": f"ctx-{counter[0]}",
                        "status": {"state": "submitted"},
                        "artifacts": [], "history": []}
                tasks[task_id] = task
                order.append(task_id)
            else:
                task = tasks.get(task_id)
                if task is None:
                    reply(rid, error={"code": -32001,
                                      "message": f"Task not found: {task_id}"})
                    continue
                if task["status"]["state"] in TERMINAL:
                    reply(rid, error={"code": -32002,
                                      "message": f"Task cannot be continued: {task_id}"})
                    continue
            task["history"].append(message)
            phrase = _text_of(message).lower().strip(" .'\"")
            if phrase in vocabulary:
                task["artifacts"].append({
                    "artifactId": f"art-{len(task['artifacts']) + 1}",
                    "name": "translation",
                    "parts": [{"kind": "text", "text": vocabulary[phrase]}],
                })
                task["status"] = {"state": "completed"}
            else:
                task["status"] = {
                    "state": "input-required",
                    "message": {"role": "agent", "parts": [
                        {"kind": "text",
                         "text": f"I don't know '{phrase}'. Provide a known phrase."}]},
                }
            reply(rid, result=task)

        elif method == "tasks/get":
            task = tasks.get(params.get("id"))
            if task is None:
                reply(rid, error={"code": -32001,
                                  "message": f"Task not found: {params.get('id')}"})
            else:
                reply(rid, result=task)

        elif method == "tasks/cancel":
            task = tasks.get(params.get("id"))
            if task is None:
                reply(rid, error={"code": -32001,
                                  "message": f"Task not found: {params.get('id')}"})
            elif task["status"]["state"] in TERMINAL:
                reply(rid, error={"code": -32002,
                                  "message": f"Task cannot be continued: {task['id']}"})
            else:
                task["status"] = {"state": "canceled"}
                reply(rid, result=task)

        else:
            reply(rid, error={"code": -32601, "message": f"Method not found: {method}"})

    return responses
